import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Terrain capture","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/terrain/docs/index.md"},"headers":[],"relativePath":"tools/terrain/docs/index.md","filePath":"tools/terrain/docs/index.md","lastUpdated":1792252169000}`),a={name:`tools/terrain/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="terrain-capture" tabindex="-1">Terrain capture <a class="header-anchor" href="#terrain-capture" aria-label="Permalink to “Terrain capture”">​</a></h1><p><code>@pumpkin-plugins/terrain</code> provides reusable terrain capture and chunk-access contracts. It does not depend on Pumpkin APIs or Minecraft wire formats, so your plugin can connect it to its own world data and encode the captured result for its needs.</p><h2 id="incremental-capture" tabindex="-1">Incremental capture <a class="header-anchor" href="#incremental-capture" aria-label="Permalink to “Incremental capture”">​</a></h2><p>Create a <code>TerrainCapture</code> for a rectangular region, then call <code>step(source, budget)</code> until it returns <code>true</code>. Each call samples at most <code>budget</code> blocks from the region, working from the top of each column downward. Adjacent blocks with the same material and light values are stored as one segment, so the result contains a material table and a segment list for each column. You can also set a maximum segment count to bound the result size.</p><p>If your source provides a column height with <code>top()</code> and you identify empty materials with <code>isEmpty</code>, capture can skip empty blocks above that height. Because each step has a block budget, a plugin can spread a large capture across server ticks instead of sampling the whole region at once.</p><p><code>AdaptiveWorkBudget</code> chooses a work limit from recent server MSPT and the measured time per work unit. Call <code>observe()</code> after each step to update its cost estimate, and pass your configured maximum to <code>next()</code>; the returned limit will not exceed it. The budget leaves a configurable portion of the tick for the server and other plugins, making it useful for incremental work that should slow down when the server is busy.</p><h2 id="chunk-access-adapters" tabindex="-1">Chunk access adapters <a class="header-anchor" href="#chunk-access-adapters" aria-label="Permalink to “Chunk access adapters”">​</a></h2><p><code>ChunkLoader</code> and <code>TerrainGenerator</code> describe optional host capabilities. <code>acquireChunk</code> first checks for an already-loaded chunk, then asks the loader to load a saved chunk. It requests generation when loading reports that the chunk is missing or loading is unavailable. A provider may report that an operation is pending, unavailable, or failed, so your caller can decide how to handle each outcome. The exported unavailable providers let a platform expose unsupported operations explicitly.</p><p>These helpers do not choose a platform&#39;s world-data adapter or an output format. Your plugin supplies the providers and source, then decides how to store the captured columns or send them to clients.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};